head.script:
scwin.ff = function() {
	dataList1.removeAll();
	for (var i = 0; i < 4; i++) {
		var new_idx = dataList1.insertRow();
		dataList1.setCellData(new_idx, "col1", i);
		dataList1.setCellData(new_idx, "col2", i + "_");
		log = "selectBox.getSelectedIndex :" + "" + sel.getSelectedIndex();
	}
	log1 = "end...setCellData..getSelectedIndex :" + sel.getSelectedIndex();
};
scwin.ff2 = function() {
	for (var i = 4; i < 8; i++) {
		var new_idx = dataList1.insertRow();
		dataList1.setCellData(new_idx, "col1", i);
		dataList1.setCellData(new_idx, "col2", i + "_");
		log2 = "selectBox.getSelectedIndex :" + "" + sel.getSelectedIndex();
	}
	log3 = "end...setCellData..getSelectedIndex :" + sel.getSelectedIndex();
};

scwin.onpageload = function() {
	window.log = '';
	window.log1 = '';
	window.log2 = '';
	window.log3 = '';
	setTimeout(function() {
		scwin.ff();
	}, 100);
	setTimeout(function() {
		scwin.ff2();
	}, 3300);
};
